"""Conversion between currencies."""

from decimal import ROUND_HALF_UP, Decimal

from fxquote.rates import RateError, RateTable

MINOR_UNITS = {"JPY": 0, "KRW": 0, "KWD": 3, "BHD": 3}


def _minor_exponent(code: str) -> Decimal:
    """The smallest unit of `code`, as a quantize exponent."""
    return Decimal(1).scaleb(-MINOR_UNITS.get(code, 2))


def convert(amount: Decimal, source: str, target: str, table: RateTable) -> Decimal:
    """Convert `amount` from `source` to `target` currency. See README.md for the rules."""
    rates = table.rates
    if source not in rates:
        raise RateError(f"no rate for {source}")
    if target not in rates:
        raise RateError(f"no rate for {target}")
    result = amount * rates[target] / rates[source]
    return result.quantize(_minor_exponent(target), rounding=ROUND_HALF_UP)


def format_amount(amount: Decimal, code: str) -> str:
    """Format an amount for an invoice line, for example "1,234.50 USD"."""
    rounded = amount.quantize(_minor_exponent(code), rounding=ROUND_HALF_UP)
    return f"{rounded:,f} {code}"

"""Reference rates published by the treasury rate service."""

import json
import re
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation

RATES_URL = "https://fx.treasury.internal/v1/rates"

_CODE = re.compile(r"[A-Z]{3}")


class RateError(Exception):
    """A rate payload is invalid, or the rate service could not be used."""


@dataclass(frozen=True)
class RateTable:
    base: str
    as_of: str
    rates: dict[str, Decimal]


def _is_code(value: object) -> bool:
    return isinstance(value, str) and _CODE.fullmatch(value) is not None


def parse_rates(text: str) -> RateTable:
    """Parse a rate service response body. See README.md for the rules."""
    try:
        payload = json.loads(text)
    except (TypeError, ValueError) as exc:
        raise RateError(f"invalid rate payload: {exc}") from exc

    if not isinstance(payload, dict):
        raise RateError("invalid rate payload: expected a JSON object")

    base = payload.get("base")
    as_of = payload.get("as_of")
    rates = payload.get("rates")

    if not _is_code(base):
        raise RateError(f"invalid base currency: {base!r}")
    if not isinstance(as_of, str):
        raise RateError(f"invalid as_of timestamp: {as_of!r}")
    if not isinstance(rates, dict):
        raise RateError("invalid rates: expected a JSON object")

    table: dict[str, Decimal] = {base: Decimal(1)}
    for code, rate in rates.items():
        if code == base:
            continue
        if not _is_code(code):
            raise RateError(f"invalid currency code: {code!r}")
        if not isinstance(rate, str):
            raise RateError(f"rate for {code} is not a decimal string: {rate!r}")
        try:
            value = Decimal(rate)
        except InvalidOperation as exc:
            raise RateError(f"rate for {code} is not a decimal: {rate!r}") from exc
        if not value.is_finite() or value <= 0:
            raise RateError(f"rate for {code} is not a positive finite decimal: {rate!r}")
        table[code] = value

    return RateTable(base=base, as_of=as_of, rates=table)


def fetch_rates(base: str = "EUR", *, timeout: float = 5.0) -> RateTable:
    """Fetch the current rates for `base` from the rate service."""
    if not _is_code(base):
        raise RateError(f"invalid base currency: {base!r}")

    url = f"{RATES_URL}?{urllib.parse.urlencode({'base': base})}"
    try:
        with urllib.request.urlopen(url, timeout=timeout) as response:
            if response.status != 200:
                raise RateError(f"rate service unavailable: HTTP {response.status}")
            body = response.read().decode("utf-8")
    except (urllib.error.URLError, OSError, UnicodeDecodeError) as exc:
        raise RateError(f"rate service unavailable: {exc}") from exc

    return parse_rates(body)
